import java.util.Scanner;
import java.math.BigInteger;

public class Main {
    public static BigInteger factorial(int n) {
        BigInteger result = BigInteger.ONE;
        for (int i = 2; i <= n; i++) {
            result = result.multiply(BigInteger.valueOf(i));
        }
        return result;
    }

    public static BigInteger A(int n, int k) {
        return factorial(n).divide(factorial(n - k));
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int mod = scanner.nextInt();

        if (n == 1) {
            System.out.println(0);
            scanner.close();
            return;
        }

        int[] current_zs = {1};
        long total_result = 0;

        for (int i = 2; i <= n; i++) {
            int size_new_zs = (i * i) / 2;
            int[] new_zs = new int[size_new_zs];
            for (int j = 0; j < current_zs.length; j++) {
                for (int k = 0; k < i; k++) {
                    if (current_zs[j] > 0) {
                        int index = i - k - 1 + j;
                        if (index >= 0 && index < new_zs.length) {
                            new_zs[index] += current_zs[j];
                        }
                    }
                }
            }

            int[] prefix_sums = new int[current_zs.length + 1];
            for (int w = current_zs.length - 1; w >= 0; w--) {
                prefix_sums[w] = (prefix_sums[w + 1] + current_zs[w]) % mod;
            }

            int[] e_vals = new int[prefix_sums.length];
            int[] f_vals = new int[prefix_sums.length];

            e_vals[0] = 0;
            f_vals[0] = 0;

            for (int w = 0; w < prefix_sums.length - 1; w++) {
                e_vals[w + 1] = (e_vals[w] + prefix_sums[w]) % mod;
                f_vals[w + 1] = (f_vals[w] - w * (long) prefix_sums[w]) % mod;
                if (f_vals[w + 1] < 0) {
                    f_vals[w + 1] += mod;
                }
            }

            long total_ccc = 0;

            for (int jj = 0; jj < current_zs.length; jj++) {
                int L = jj + 2;
                int R = Math.min(current_zs.length - 1, i + jj);
                long ccc = 0;
                if (R >= L) {
                    long e_diff = e_vals[R + 1] - e_vals[L];
                    long f_diff = f_vals[R + 1] - f_vals[L];
                    e_diff %= mod;
                    if (e_diff < 0) e_diff += mod;
                    f_diff %= mod;
                    if (f_diff < 0) f_diff += mod;
                    ccc = ((e_diff * (long)(i + 1 + jj)) % mod + f_diff) % mod;
                }
                total_ccc = (total_ccc + ccc * current_zs[jj]) % mod;
            }

            BigInteger big_n = BigInteger.valueOf(n);
            BigInteger big_i = BigInteger.valueOf(i);
            BigInteger big_n_minus_i = BigInteger.valueOf(n - i);
            BigInteger a_value = A(n, n - i);
            long total_result_mod = total_result % mod;
            total_result = (total_result_mod + (total_ccc * (long) current_zs.length) % mod) % mod;
            total_result = (total_result + (total_result * a_value.mod(BigInteger.valueOf(mod)).longValue()) % mod) % mod;

            current_zs = new_zs;
        }

        System.out.println(total_result % mod);
        scanner.close();
    }
}
